function run(argv){
  var D=argv[0], out=[];
  var base=rd(D+'/sim.js');
  var lens=[2600,2800];
  for (var li=0;li<lens.length;li++){
    var f=new Function(base.replace('__AIRLEN__',lens[li])+';return rampartSimulate;')();
    var A=function(){return {plan:function(s){var a=[],g=s.gold;for(var i=0;i<s.slots.length;i++){var sl=s.slots[i];if(!sl.turret&&g>=50){a.push({op:"build",slot:sl.slot,type:"bolt"});g-=50;}}return a;}};};
    var B=function(){return {plan:function(s){ if(s.wave==1)return[{op:"build",slot:3,type:"cannon"},{op:"build",slot:6,type:"frost"}]; if(s.wave==3)return[{op:"upgrade",slot:3},{op:"build",slot:12,type:"flak"}]; if(s.wave==6)return[{op:"build",slot:8,type:"lance"},{op:"sell",slot:6}]; return[];}};};
    var a=f(A,42,12020), b=f(B,7,12020);
