function createStrategy() {
  const P = { frost: 30, airW: 0.35, splash: 1.6, maxFrost: 3, maxFlak: 2, reserve: 0 };
  const SL = [[3,3],[5,5],[7,4],[7,8],[9,9],[10,5],[11,8],[13,8],[14,5],[15,2],[16,7],[17,4],[19,8],[20,10],[22,9],[3,7]];
  const TT = { bolt: { c: 50, d: 26, p: 8, r: 300, sp: 0, pi: 0, g: 1, a: 1 }, cannon: { c: 90, d: 60, p: 24, r: 260, sp: 1, pi: 0, g: 1, a: 0 },
    frost: { c: 70, d: 10, p: 12, r: 240, sp: 0, pi: 0, g: 1, a: 1 }, lance: { c: 120, d: 180, p: 36, r: 360, sp: 0, pi: 1, g: 1, a: 0 },
    flak: { c: 80, d: 40, p: 10, r: 320, sp: 1, pi: 0, g: 0, a: 1 } };
  const TYPES = Object.keys(TT);
  const sample = (pts) => { const out = []; for (let i = 0; i < pts.length - 1; i++) { const a = pts[i], b = pts[i + 1]; const n = Math.abs(b[0] - a[0]) + Math.abs(b[1] - a[1]);
    for (let j = 0; j < n * 4; j++) out.push([(a[0] + (b[0] - a[0]) * j / (n * 4)) * 100 + 50, (a[1] + (b[1] - a[1]) * j / (n * 4)) * 100 + 50]); } return out; };
  const GS = sample([[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]]), AS = sample([[0,6],[21,6],[21,11],[23,11]]);
  const cov = (s, range, pts) => { const x = SL[s][0] * 100 + 50, y = SL[s][1] * 100 + 50; let n = 0; for (const p of pts) { const dx = p[0] - x, dy = p[1] - y; if (dx * dx + dy * dy <= range * range) n++; } return n / 100 * 25 / 4 * 4 / 4; };
  const dmgAt = (t, tier) => { let d = TT[t].d; for (let i = 1; i < tier; i++) d = Math.floor(d * 16 / 10); return d; };
  const value = (s, t, tier, w) => {
    const T = TT[t], r = T.r + 30 * (tier - 1); const arm = 0.75 * Math.floor(w / 4) + 0.25 * (6 + w);
    const d = T.pi ? dmgAt(t, tier) : Math.max(1, dmgAt(t, tier) - arm);
    let dps = d / T.p; if (T.sp) dps *= P.splash; if (t === 'frost') dps = P.frost / T.p;
    let c = 0; if (T.g) c += cov(s, r, GS); if (T.a) c += P.airW * cov(s, r, AS);
    return dps * c;
  };
  return {
    plan(state) {
      const w = state.wave, acts = []; let g = state.gold - P.reserve;
      const tur = state.slots.map(s => s.turret ? { type: s.turret.type, tier: s.turret.tier } : null);
      for (let it = 0; it < 30; it++) {
        const nf = tur.filter(t => t && t.type === 'frost').length, nk = tur.filter(t => t && t.type === 'flak').length;
        let best = null, bv = 0;
        for (let s = 0; s < 16; s++) {
          const t = tur[s];
