function out(pan) { const g = AC.createGain(); let last = g; if (AC.createStereoPanner) { const p = AC.createStereoPanner(); p.pan.value = clamp(pan, -1, 1); g.connect(p); last = p; } last.connect(master); return g; }
function track(n, dur) { active.add(n); n.onended = () => active.delete(n); n.start(AC.currentTime); n.stop(AC.currentTime + dur + 0.02); }
function tone(type, f0, f1, dur, vol, pan, delay) { const o = AC.createOscillator(), g = out(pan), T = AC.currentTime; o.type = type; o.frequency.setValueAtTime(f0, T); o.frequency.exponentialRampToValueAtTime(Math.max(1, f1), T + dur); g.gain.setValueAtTime(vol, T); g.gain.exponentialRampToValueAtTime(0.0001, T + dur); o.connect(g); track(o, dur); }
function noise(dur, vol, ftype, f, pan, f2) { const s = AC.createBufferSource(), fl = AC.createBiquadFilter(), g = out(pan), T = AC.currentTime; s.buffer = noiseBuf; fl.type = ftype; fl.frequency.setValueAtTime(f, T); if (f2) fl.frequency.exponentialRampToValueAtTime(f2, T + dur); g.gain.setValueAtTime(vol, T); g.gain.exponentialRampToValueAtTime(0.0001, T + dur); s.connect(fl); fl.connect(g); s.start(T, ar() * 1.5); s.stop(T + dur + 0.02); active.add(s); s.onended = () => active.delete(s); }
function playShot(type, x) { const p = x / 24 * 2 - 1, j = 0.9 + ar() * 0.2;
  if (type === 'bolt') tone('square', 900 * j, 300, 0.07, 0.05, p); else if (type === 'cannon') { tone('sine', 150 * j, 45, 0.22, 0.28, p); noise(0.15, 0.12, 'lowpass', 900, p); }
  else if (type === 'frost') { tone('triangle', 1900 * j, 1100, 0.12, 0.05, p); noise(0.1, 0.04, 'highpass', 5000, p); }
  else if (type === 'lance') { tone('sawtooth', 260 * j, 55, 0.28, 0.1, p); noise(0.2, 0.08, 'bandpass', 1500, p, 300); } else { noise(0.1, 0.1, 'bandpass', 2200, p); tone('sine', 520 * j, 240, 0.1, 0.08, p); } }
const PRI = { lance: 0, cannon: 1, flak: 2, bolt: 3, frost: 4 };
function startWind() { if (wind || !AC) return; const s = AC.createBufferSource(), f = AC.createBiquadFilter(), g = AC.createGain(); s.buffer = noiseBuf; s.loop = true; f.type = 'bandpass'; f.frequency.value = 280; f.Q.value = 0.7; g.gain.value = 0.05; s.connect(f); f.connect(g); g.connect(master); s.start(); wind = s; active.add(s); }
function stopAllAudio() { for (const n of active) { try { n.stop(); } catch (e) { } } active.clear(); wind = null; }
let audioOn = false;
function setAudio(on) { if (!AC || on === audioOn) return; audioOn = on; const T = AC.currentTime; master.gain.cancelScheduledValues(T); master.gain.setValueAtTime(master.gain.value, T);
  if (on) master.gain.linearRampToValueAtTime(0.6, T + 0.03); else { master.gain.linearRampToValueAtTime(0, T + 0.04); setTimeout(() => { if (!audioOn) stopAllAudio(); }, 60); } }
let lastAudioK = 0;
function audioTick(t, playing) { const kN = Math.floor(t * 20); if (AC && playing && audioOn && kN > lastAudioK && kN - lastAudioK <= 12) { const shots = [];
    for (let kk = lastAudioK + 1; kk <= Math.min(kN, LAST); kk++) { const E = evs[kk]; if (!E) continue; for (const e of E) { const px = e.x !== undefined ? e.x / 100 : e.slot !== undefined ? SLOTS[e.slot][0] + 0.5 : 23.5;
        if (e.t === 'shot') shots.push(e); else if (e.t === 'K') { tone('sine', 650, 200, 0.07, 0.05, px / 24 * 2 - 1); } else if (e.t === 'wave') { tone('sawtooth', 110, 165, 0.7, 0.07, 0); tone('sawtooth', 112, 168, 0.7, 0.07, 0); tone('square', 220, 330, 0.5, 0.025, 0); }
        else if (e.t === 'L') { noise(0.18, 0.2, 'lowpass', 700, 0.95); tone('square', 440, 440, 0.12, 0.06, 0.95); tone('square', 330, 330, 0.12, 0.06, 0.95); }
        else if (e.t === 'F') { tone('sine', 90, 24, 2.4, 0.5, 0.9); noise(2.6, 0.35, 'lowpass', 220, 0.9, 60); } } }
    shots.sort((a, b) => PRI[a.type] - PRI[b.type]); const nowT = AC.currentTime; while (recentShots.length && recentShots[0] < nowT - 1) recentShots.shift();
    for (const e of shots) { if (recentShots.length >= 12) break; recentShots.push(nowT); playShot(e.type, SLOTS[e.slot][0] + 0.5); } }
  if (AC && playing && audioOn && t >= FALLT + 2 && !wind) startWind(); lastAudioK = kN; }

/* ---------- state machine ---------- */
const $ = (id) => document.getElementById(id); const cd = $('countdown'), scrub = $('scrubber'), bt = $('btn-toggle'), ip = $('icon-pause'), iplay = $('icon-play');
let state = 'COUNTDOWN', speed = 1, cdEl = 0, holdEl = 0, lastTs = null;
function icons() { const playing = state === 'PLAYING' || state === 'COUNTDOWN' || state === 'REFIRE_HOLD'; ip.style.display = playing ? '' : 'none'; iplay.style.display = playing ? 'none' : ''; bt.setAttribute('aria-label', playing ? 'Pause' : 'Play'); }
function hideCd() { cd.style.display = 'none'; cd.textContent = ''; }
function setSim(t) { simTime = t; scrub.value = t === 0 ? '0' : t.toFixed(3); }
bt.addEventListener('click', () => { if (state === 'PLAYING') state = 'PAUSED'; else if (state === 'COUNTDOWN' || state === 'REFIRE_HOLD') { hideCd(); setSim(0); state = 'PAUSED'; } else if (state === 'PAUSED') state = 'PLAYING'; else if (state === 'ENDED') { hideCd(); setSim(0); state = 'PLAYING'; lastAudioK = 0; } icons(); });
document.querySelectorAll('.speed-pill').forEach(b => b.addEventListener('click', () => { speed = parseFloat(b.dataset.speed); document.querySelectorAll('.speed-pill').forEach(o => { const on = o === b; o.classList.toggle('is-active', on); o.setAttribute('aria-checked', on ? 'true' : 'false'); }); }));
scrub.addEventListener('input', () => { hideCd(); simTime = clamp(parseFloat(scrub.value) || 0, 0, DURATION); state = 'PAUSED'; icons(); setAudio(false); render(simTime); lastAudioK = Math.floor(simTime * 20); });
$('btn-refire').addEventListener('click', () => { hideCd(); setSim(0); holdEl = 0; state = 'REFIRE_HOLD'; icons(); setAudio(false); lastAudioK = 0; render(0); });
function frame(ts) {
  requestAnimationFrame(frame); const raw = lastTs === null ? 0 : (ts - lastTs) / 1000; lastTs = ts; const dt = Math.min(Math.max(raw, 0), 0.1);
  if (state === 'COUNTDOWN') { cdEl += dt; if (cdEl >= 3) { hideCd(); state = 'PLAYING'; icons(); } else { cd.style.display = 'block'; cd.textContent = String(3 - Math.floor(cdEl)); } }
  else if (state === 'REFIRE_HOLD') { holdEl += dt; if (holdEl >= 1) { state = 'PLAYING'; icons(); } }
  else if (state === 'PLAYING') { simTime = Math.min(DURATION, simTime + dt * speed); scrub.value = simTime.toFixed(3); if (simTime >= DURATION) { simTime = DURATION; scrub.value = DURATION.toFixed(3); state = 'ENDED'; icons(); } }
  const playing = state === 'PLAYING'; setAudio(playing); render(simTime); audioTick(simTime, playing);
  if (!playing) lastAudioK = Math.floor(simTime * 20);
}
resize(); icons(); render(0); requestAnimationFrame(frame);
})();

